INSERT INTO `jenjang_pendidikan` (`id`, `judul`, `deskripsi`, `jenjang`, `nama_unit`, `image`) VALUES
(1, 'UNIT / JENJANG PENDIDIKAN', 'Menjawab perkembangan zaman sehingga nanti akan lahir generasi masa depan yang menjadi panutan karena kecerdasan akal, keserasian penampilan, dan kelemahlembutannya dalam bergaul serta menjadi generasi Insan Kamil dan Penerang Peradaban yang mampu mendedikasikan pribadinya bagi kejayaan ummat secara profesional dan berwawasan luas, Yayasan SMK PKP 1 Jakarta Islamic School mendirikan Sekolah:', NULL, NULL, NULL),
(2, NULL, NULL, 'TKIT', 'SMK PKP 1 Jakarta 1', 'http://localhost:5001/public/img/1.png'),
