INSERT INTO `kurikulum_sdit` (`id`, `judul`, `deskripsi`) VALUES
(1, 'Kurikulum SMK PKP 1 Jakarta', 'Konsep SMK PKP 1 Jakarta Islamic School cendikia dalam Aspek Dzikir, Menjadikan anak memiliki kecerdasan emosi dan spiritual dengan melakukan keteladanan berdasarkan Al Qur’an dan Hadist. Aspek Fikir, menjadikan anak memiliki logika berfikir (Falsafah Ilmu Pengetahuan) dengan pembelajaran (Active Learning) yang mengarah kepada terbentuknya ilmuan cendikiawan muslim. Aspek Leadership, menjadikan anak memiliki semangat kepemimpinan sebagai perwujudan “Khalifah Fil ardh” dan “Rahmatan Lil Alamin” dengan ragam kegiatan seperti outbound, Dinamic group dan lain sebagainya.');

