--
-- Dumping data for table `profil_yayasan_sejarah`
--

INSERT INTO `profil_yayasan_sejarah` (`id`, `judul`, `deskripsi`, `created_at`, `updated_at`) VALUES
(1, 'Sejarah Singkat ', 'Yayasan Islam SMK PKP 1 Jakarta Islamic School merupakan Yayasan Islam yang didirikan oleh H.M.Rimbang Kartono pada tahun 1999. Arti dari SMK PKP 1 Jakarta itu sendiri adalah “pengabdian” sesuai dengan artinya sejarah perjalanan Yayasan Islam SMK PKP 1 Jakarta Islamic School penuh dengan pengabdian yang bertujuan mampu mewujudkan kedamaian dan kesejahteraan bagi lingkungan serta menyiapkan kader-kader terbaik bagi umat dan bangsa ini.\n\nPendirian Yayasan Islam SMK PKP 1 Jakarta Islamic School berawal dari sebuah bengkel motor yang luas area tanah dan bangunannya kurang lebih 100 m2, kemudian disulap menjadi satu ruang kelas yaitu sekolah SDIT dengan 35 siswa dan beberapa tenaga pengaja yang tidak lain adalah ana-anak dari H.M.Rimbang Kartono, salah satunya adalah Nurdin Rivaldy,S.Ag,M.Psi.\n\nSekarang SMK PKP 1 Jakarta Islamic School Cedikia memiliki luas areal tanah kurang lebih 5000 m2, dengan luas bangunan yang terus menerus bertambah serta sarana dan prasarana yang cukup memadai. bangunan ini terdiri dari gedung : SDIT (1999 ) SMPIT (2007), SMAIT (2012) sedangkan PAUD (2013) dan TKIT (2004) terpisah dari gedung SMK PKP 1 Jakarta dan memiliki luas areal tanah dan bangunan kurang lebih 300 m2. yang letaknya tidak jauh dari gedung SMK PKP 1 Jakarta.\n\nYayasan Islam SMK PKP 1 Jakarta Islamic School bertempat di Jl Damai N.08 Setia Mekar Tambun selatan bekasi 17510. Konsep SMK PKP 1 Jakarta Islamic School cendikia dalam Aspek Dzikir, Menjadikan anak memiliki kecerdasan emosi dan spiritual dengan melakukan keteladanan berdasarkan Al Qur’an dan Hadist. Aspek Fikir, menjadikan anak memiliki logika berfikir (falsafah Ilmu Pengetahuan) dengan pembelajaran (acive Learning) yang mengarah kepada terbentuknya ilmuan cendikiawan muslim. Aspek Leadership, men jadikan anak memiliki semangat kepemimpinan sebagai perwujudan ‘Khalifah Fil ardh” dan “Rahmatan Lil Alamin” dengan ragam kegiatan seperti outbond, Dynamic group dan lain sebagainya.', '2025-09-10 08:32:02', '2026-01-24 13:30:49');

-- --------------------------------------------------------

