INSERT INTO `program_kejuruan_smkit` (`id`, `kategori`, `deskripsi`, `created_at`, `updated_at`) VALUES
(1, 'Multimedia', 'Meneliti peserta didik melalui penilaian kompetensi dasar, penilaian pengetahuan, penilaian keterampilan, dan penilaian sikap profesional dan mandiri sesuai jenjang pendidikan.\n\nKompetensi Khusus Multimedia menitik beratkan pada pembelajaran dasar-dasar multimedia.\n\nKompetensi Khusus Multimedia menitik beratkan pada pembelajaran dasar-dasar multimedia yang berupa pengenalan software dasar dan editing video.\n\nMembentuk dan menyiapkan tenaga kerja yang kompeten dalam bidang multimedia.\n\nMenyiapkan peserta didik untuk menguasai keterampilan multimedia profesional.\n\nMembentuk dan menyiapkan tenaga kerja yang kompeten dalam bidang multimedia yang berupa pengenalan audio dan editing video.\n\nMembentuk dan menyiapkan tenaga kerja yang kompeten dalam bidang multimedia profesional.', '2025-09-22 09:14:10', '2025-09-22 09:38:03');

