CREATE TABLE `visi_misi_sasaran_smait` (
  `id` int(11) NOT NULL,
  `tipe` enum('Visi','Misi','Sasaran') NOT NULL,
  `deskripsi` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

--
-- Dumping data for table `visi_misi_sasaran_smait`
--

INSERT INTO `visi_misi_sasaran_smait` (`id`, `tipe`, `deskripsi`) VALUES
(1, 'Visi', 'Terdepan dalam membentuk insan taqwa yang cerdas, cendikia, berakhlak mulia, berjiwa leadership, entrepreneurship.'),
(2, 'Misi', 'a. Penanaman dan aplikasi nilai-nilai akhlak Islami baik di sekolah, di rumah, maupun di masyarakat.  b. Melaksanakan proses pembelajaran aktif, inovatif, kreatif, efektif, dan menyenangkan berbasis teknologi informasi.  c. Meningkatkan kompetensi tenaga pendidik dan kependidikan yang bertakwa, berakhlak mulia, dan berwawasan global.  d. Melaksanakan koordinasi dan membangun jaringan kerja sama yang baik dengan semua stakeholder.  e. Tersedianya sarana dan prasarana pembelajaran yang berbasis multimedia dan teknologi informasi.'),
(3, 'Sasaran', 'a. Memantapkan dasar-dasar aqidah dan akhlak islamiyah peserta didik untuk menumbuh kembangkan potensi fitrah dan fungsi kekhalifahannya, tekun beribadah yang tercermin dari perilakunya, insan Qur\'ani, Islami, tawadhu, teladan bagi keluarga dan lingkungan.  b. Membiasakan peserta didik berdisiplinan tinggi, kreatif, mandiri, optimis, tidak mengenal putus asa, dan selalu bersemangat untuk terus berprestasi.  c. Menciptakan peserta didik untuk memiliki kemampuan akademis yang tinggi, kemampuan ilmiah, keterampilan hidup, kepemimpinan dan mempunyai kematangan emosional.  d. Menciptakan peserta didik yang memiliki jiwa kepemimpinan (leadership) yang tangguh sehingga kelak akan menjadi pemimpin yang sukses untuk dirinya, keluarga, masyarakat dan bangsa.  e. Menumbuhkan jiwa entrepreneurship (kewirausahaan) peserta didik sehingga mampu menciptakan inovasi usaha, kemandirian, dan keterampilan hidup untuk kemajuan dan kesuksesannya di masa datang.  f. Membekali peserta didik dengan pengetahuan dan keterampilan sehingga mampu bersaing dan siap melanjutkan ke perguruan tinggi terbaik.  g. Menumbuhkan pada peserta didik ghirah (semangat juang) Islam dan peduli terhadap sesama umat Islam.');

