INSERT INTO `visi_misi_sasaran_smpit` (`id`, `tipe`, `deskripsi`) VALUES
(1, 'Visi', 'Sekolah Islam Terdepan Dalam Mencetak Generasi Berakhlak Mulia, Unggul, Dan Kompetitif'),
(2, 'Misi', 'a. Menyelenggarakan pendidikan dengan standar nasional yang terintegrasi nilai-nilai Islam.  b. Melaksanakan pembelajaran aktif, kreatif, kolaboratif, leadership, dan Islami.  c. Meningkatkan kualitas keilmuan dan keislaman peserta didik, pendidik dan tenaga kependidikan.  d. Mewujudkan pelayanan terbaik dalam setiap aktivitas di sekolah dan di masyarakat.  e. Menjalin kerjasama yang harmonis dengan semua stakeholder.  f. Penggunaan media, sarana dan prasarana berstandar teknologi modern.'),
(3, 'Sasaran', 'Tujuan Sekolah SMK PKP 1 Jakarta yaitu meningkatkan kecerdasan, pengetahuan, kepribadian, akhlak mulia, serta keterampilan untuk hidup mandiri dan mengikuti pendidikan lebih lanjut.');

