--
-- Dumping data for table `visi_misi_tujuan_tkit_1`
--

INSERT INTO `visi_misi_tujuan_tkit_1` (`id`, `visi`, `misi`, `tujuan`) VALUES
(1, 'Sekolah Islam Terdepan Dalam Mencetak Generasi Berakhlak Mulia, Unggul, Dan Kompetitif', 'a. Menanamkan karakter dasar islam melalui praktek ajaran agama Islam sesuai perkembangan anak.\r\n\r\n     b. Menciptakan kondisi lingkungan bermain dan belajar yang menyenangkan, edukatif, kondusif, dan konstruktif.\r\n\r\n     c. Membekali anak dengan persiapan memasuki jenjang pendidikan tingkat dasar.\r\n\r\n     d. Memberikan pelayanan terbaik bagi siswa dan orang tua.', 'Aspek-aspek Pendidikan anak usia dini yang menjadi sasaran dari berbagai aktivitas di TK Islam Terpadu SMK PKP 1 Jakarta diantaranya:\r\na.Pengembangan nilai-nilai agama dan moral\r\nb.Pengembangan sosial emosional\r\nc.Pengembangan bahasa\r\nd.Pengembangan kognitif\r\ne.Pengembangan fisik ( meliputi: motorik kasar, motorik halus, dan Kesehatan fisik )\r\nf.Pengembangan seni dan kreatifitas\r\n\r\nKegiatan pembelajaran di TK Islam Terpadu dibagi menjadi tiga kelompok belajar yaitu :\r\na. Kelompok Bermain (usia 3-4 tahun )\r\nb. TK A ( usia 4-5 tahun )\r\nc. TK B ( usia 5-6 tahun )\r\nDengan kegiatan ini lebih ditekankan dalam perkembangan motorik halus dan motorik kasar serta pengembangan karakter dan kemandirian melalui kegiatan – kegiatan pembiasaan yang baik bagi siswa');

