INSERT INTO `yayasan` (`id`, `judul`, `deskripsi`, `tahun_didirikan`, `pendiri`, `ketua`, `link_selengkapnya`) VALUES
(1, 'Sambutan Ketua Yayasan', 'SMK PKP 1 Jakarta Islamic School merupakan yayasan pendidikan Islam yang didirikan oleh H.M. Rimbang Kartono pada tahun 1999. Arti dari SMK PKP 1 Jakarta itu sendiri adalah \"pengabdian\" sesuai dengan arti nya sebagai perjalanan Yayasan Pendidikan Islam SMK PKP 1 Jakarta Islamic School penuh dengan pengabdian yang bertujuan untuk mewujudkan kedamaian dan kesejahteraan bagi lingkungan serta menyempurnakan kader-kader terpilih bagi umat dan bangsa ini.', 1999, 'H.M. Rimbang Kartono', 'Nurdin Rivaldy, S.Ag, M.Psi', '/profil');

